const MIN = 60_000
const HOUR = 60 * MIN
const DAY = 24 * HOUR
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

export function usd(n: number, isEstimate = false): string {
  const [whole = '0', cents = '00'] = n.toFixed(2).split('.')
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',')

  return `${isEstimate ? '~' : ''}$${grouped}.${cents}`
}

export function tokens(n: number): string {
  if (n < 1000) {
    return String(Math.round(n))
  }
  if (n < 1_000_000) {
    return `${Math.round(n / 1000)}k`
  }

  return `${Number((n / 1_000_000).toFixed(1))}M`
}

export function duration(ms: number): string {
  if (ms < MIN) {
    return '<1m'
  }
  if (ms < HOUR) {
    return `${Math.floor(ms / MIN)}m`
  }
  if (ms < DAY) {
    return `${Math.floor(ms / HOUR)}h${Math.floor((ms % HOUR) / MIN)}m`
  }

  return `${Math.floor(ms / DAY)}d${Math.floor((ms % DAY) / HOUR)}h`
}

export function weeklyReset(iso: string, now: number): string {
  const at = Date.parse(iso)
  const hours = (at - now) / HOUR

  return hours < 24 ? `${Math.max(1, Math.ceil(hours))}h` : (WEEKDAYS[new Date(at).getDay()] ?? '')
}

export function clockTime(ms: number): string {
  const d = new Date(ms)
  const hours = d.getHours()
  const minutes = String(d.getMinutes()).padStart(2, '0')

  return `${hours % 12 || 12}:${minutes}${hours < 12 ? 'am' : 'pm'}`
}

/** Minutes and seconds, `1:05`, or hours too once past an hour; a clock-style running time. */
/** How long ago, in its largest unit alone: `just now`, `3m ago`, `1h ago`, `2d ago`. */
export function ago(ms: number): string {
  const m = Math.floor(Math.max(0, ms) / 60_000)
  if (m < 1) {
    return 'just now'
  }

  return m < 60 ? `${m}m ago` : m < 24 * 60 ? `${Math.floor(m / 60)}h ago` : `${Math.floor(m / (24 * 60))}d ago`
}

export function elapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  const [h, m, sec] = [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60]
  const pad = (n: number) => String(n).padStart(2, '0')

  return h > 0 ? `${h}:${pad(m)}:${pad(sec)}` : `${m}:${pad(sec)}`
}

/**
 * How much faster a pane row's faint note shrinks than the name before it (both CSS and Yoga shrink by flexShrink
 * times width), so the layout cuts the note first and the name only once the note is gone. They are separate Texts in
 * boxes of their own: the desktop wraps a Text with another nested in it rather than cutting it.
 */
export const NOTE_SHRINK = 1000

